// src/pdf/invoiceTemplate.ts — layout constants and block builders for invoice PDFs.
export const PAGE = { width: 595, height: 842, margin: 48 } as const;
export const FONTS = { body: 'Inter-Regular', bold: 'Inter-SemiBold', mono: 'JetBrainsMono-Regular' } as const;

export type LineItem = { sku: string; description: string; qty: number; unitCents: number; taxRate: number };

export function headerBlock(invoiceNo: string, issuedAt: string) {
  return { kind: 'header', invoiceNo, issuedAt, logo: 'assets/logo.svg', heightPt: 96 };
}

export function lineItemRows(items: LineItem[]) {
  return items.map((it) => ({
    kind: 'row',
    cells: [it.sku, it.description, String(it.qty), centsToMoney(it.unitCents), pct(it.taxRate), centsToMoney(rowTotalCents(it))],
    heightPt: 22,
  }));
}

export function rowTotalCents(it: LineItem): number {
  const net = it.qty * it.unitCents;
  return Math.round(net * (1 + it.taxRate));
}

export function totalsBlock(items: LineItem[]) {
  const net = items.reduce((s, it) => s + it.qty * it.unitCents, 0);
  const tax = items.reduce((s, it) => s + Math.round(it.qty * it.unitCents * it.taxRate), 0);
  return { kind: 'totals', netCents: net, taxCents: tax, grossCents: net + tax };
}

const centsToMoney = (c: number) => (c / 100).toFixed(2) + ' EUR';
const pct = (r: number) => (r * 100).toFixed(1) + '%';
