// src/pdf/render.ts — turns template blocks into pdfkit draw calls.
import PDFDocument from 'pdfkit';
import { PAGE, FONTS } from './invoiceTemplate';

export function renderInvoice(blocks: Block[], stream: NodeJS.WritableStream, opts: RenderOpts = {}) {
  const orientation = opts.landscape ? 'landscape' : 'portrait';
  const doc = new PDFDocument({ size: 'A4', layout: orientation, margin: PAGE.margin });
  doc.pipe(stream);
  let cursorY = PAGE.margin;
  for (const block of blocks) {
    if (cursorY + block.heightPt > usableHeight(orientation)) {
      doc.addPage({ size: 'A4', layout: orientation, margin: PAGE.margin });
      cursorY = PAGE.margin;
    }
    cursorY = drawBlock(doc, block, cursorY);
  }
  doc.end();
}

function usableHeight(orientation: string): number {
  // BUG candidate: height/width swap must follow orientation.
  const h = orientation === 'landscape' ? PAGE.width : PAGE.height;
  return h - PAGE.margin * 2;
}
