// test/pdf/render.test.ts
import { renderInvoice } from '../../src/pdf/render';
import { collectPdfText, pageBoxes } from '../support/pdfProbe';

describe('renderInvoice', () => {
  it('keeps rows inside the printable area in portrait', async () => {
    const { boxes } = await pageBoxes(sampleBlocks(40), {});
    expect(boxes.every((b) => b.y + b.h <= 842 - 48)).toBe(true);
  });

  it('breaks pages between blocks, never inside a row', async () => {
    const { boxes, pages } = await pageBoxes(sampleBlocks(120), {});
    expect(pages).toBeGreaterThan(1);
    expect(boxes.filter((b) => b.split).length).toBe(0);
  });
});
